def trailing_zeroes(n):
    factorial = 1
    for i in range(2, n + 1):
        factorial *= i               # build up the full factorial, growing enormous very fast
    count = 0
    while factorial % 10 == 0:
        factorial //= 10               # strip one trailing zero at a time
        count += 1
    return count


if __name__ == "__main__":
    n = 5
    print(trailing_zeroes(n))

