import java.util.*;

public class Main {
    int trailingZeroes(int n) {
        long factorial = 1;
        for (int i = 2; i <= n; i++) {
            factorial *= i;                // build up the full factorial, growing enormous very fast
            // warning: this silently overflows a 64-bit long once n reaches the low 20s
        }
        int count = 0;
        while (factorial % 10 == 0) {
            factorial /= 10;                 // strip one trailing zero at a time
            count++;
        }
        return count;
    }

    public static void main(String[] args) {
        int n = 5;
        Main solution = new Main();
        System.out.println(solution.trailingZeroes(n));
    }
}

