def trailing_zeroes(n):
    count = 0
    power_of_five = 5
    while power_of_five <= n:
        count += n // power_of_five    # count multiples of this power of 5 up to n
        power_of_five *= 5               # move to the next power: 25, 125, 625, ...
    return count


if __name__ == "__main__":
    n = 5
    print(trailing_zeroes(n))

